"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5875],{3321:(t,n,i)=>{var e=i(4645);i.o(e,"useRouter")&&i.d(n,{useRouter:function(){return e.useRouter}})},5291:(t,n,i)=>{i.d(n,{C:()=>e});let e={project:"פרק 6 - חמש מצוות היסוד",screens:[{id:"00",kind:"film",section:"פתיחה",title:"סרטון הפתיחה"},{id:"01",kind:"opening",section:"פתיחה",title:"מחמש המצוות לחמש פעולות",content:["בקוראן נכתבו מצוות נוספות, כמו איסור הלוואה בריבית, מצוות כיבוד הורים, איסור אכילת חזיר, דם ובשר נבלה ועוד, אך חמש מצוות אלו נחשבות לעמודי האסלאם (ארכאן אלאסלאם אלח'מסה)."],nextLabel:"מתחילים בשהאדה",drawerTitle:"הסיפור המלא",drawerContent:["יש מסורת באסלאם, המיוחסת לעֻמַר בן אלח'טאב (הח'ליף השני), שמוחמד ישב עם חבריו (הצחאבה) בעיר מדינה כשלפתע ניגש אליהם אדם עם בגדים מבהיקים מלובן ושערו שחור, ונראה שלמרות שהגיע ממרחק, סימני המסע לא ניכרו עליו.","האדם ניגש למוחמד, הצמיד את ברכיו לברכיו והניח את ידיו על ירכיו.","פנה האיש למוחמד ואמר: יא מוחמד, מהו האסלאם?","ענה לו מוחמד: האסלאם הוא שעליך להאמין שאין אל מבלעדי אללה, שמוחמד הוא שליחו, עליך להתפלל חמש תפילות ביום, לתת צדקה, לצום את צום הרמדאן ולעלות לרגל פעם בחיים אם ביכולתך.",'לאחר מספר שאלות נוספות למוחמד, ענה לו: "אמת אמרת", ונעלם.',"לפליאתו של עמר, שאל אותו מוחמד האם הוא יודע מי האיש, והשיב לו בשלילה.",'ענה לו מוחמד: "זהו המלאך גבריאל".'],actionDetails:[{commandment:"השהאדה",action:"להעיד",quote:"אין אל מבלעדי אללה ושמוחמד הוא שליחו."},{commandment:"התפילה",action:"להתפלל",quote:"חמש תפילות ביום."},{commandment:"הצדקה",action:"לתת",quote:"לתת צדקה."},{commandment:"צום רמדאן",action:"לצום",quote:"לצום את צום הרמדאן."},{commandment:"החג'",action:"לעלות לרגל",quote:"לעלות לרגל פעם בחיים, אם ביכולתך."}]},{id:"sh-1",kind:"content",section:"השהאדה",title:"המילה ומשמעה",content:["המילה שהאדה נגזרת מן השורש הערבי ש-ה-ד, שמשמעותו עדות / מתן עדות. יתכן ומילה זו מקורה מארמית, שכן היא מוזכרת במקרא (גל-עד; יגר שהדותא, בראשית לא:מז)."]},{id:"sh-2",kind:"content",section:"השהאדה",title:"תוכן העדות",content:["על המוסלמי להעיד שאין אל מבלעדי אללה ושמוחמד הוא שליחו.","ההצהרה על ייחוד האל מבטאת את עיקרון המונותאיזם באופן מושלם, ואת דחיית עבודת האלילים, שהיה נהוג טרם תקופת האסלאם."]},{id:"sh-3",kind:"content",section:"השהאדה",title:"מתי נאמרת השהאדה",content:["משפט זה נאמר בקריאה לתפילה (אד'אן) על ידי המואזין, וכן במהלך התפילה עצמה.","כאשר אדם מבקש לקבל על עצמו את דת האסלאם, הוא מצהיר על אמונתו באמצעות אמירת השהאדה. במרבית הקהילות באסלאם הדרך לעשות זאת היא אמירת השהאדה שלוש פעמים בפני שני עדים כשרים (גברים ובוגרים)."]},{id:"sh-v",kind:"visual",section:"השהאדה",title:"מן המילה אל העדות",lead:"המילה עצמה, בשלוש שכבות: הכתב הערבי, התעתיק העברי והמשמעות."},{id:"sh-c",kind:"check",section:"השהאדה",title:"בדיקת הבנה קצרה",check:{type:"multi",question:"מתי נאמרת השהאדה?",instruction:"סמנו את כל המצבים המתאימים.",options:[{text:"בקריאה לתפילה",right:!0},{text:"במהלך התפילה",right:!0},{text:"בעת קבלת דת האסלאם",right:!0},{text:"בזמן שבירת צום רמדאן",right:!1},{text:"במהלך העלייה לרגל",right:!1}],ok:"נכון. השהאדה נאמרת בקריאה לתפילה, במהלך התפילה ובעת קבלת דת האסלאם.",try:"חלק מהבחירות אינן מתאימות. חזרו למצבים שבהם נאמרת העדות ונסו שוב.",hint:"חפשו את שלושת המצבים שהוזכרו במפורש בתוכן שקראתם."}},{id:"sh-t",kind:"transition",section:"השהאדה",title:"סיום השהאדה",text:"סיימנו את השהאדה – העדות המבטאת את יסודות האמונה. כעת נעבור למצוות התפילה.",nextLabel:"עוברים לתפילה"},{id:"pr-1",kind:"content",section:"התפילה",title:"מהמסע הלילי אל חמש התפילות",content:["לפי המסורת האסלאמית, מצוות התפילה נקשרה למסע הלילי ולעלייה לשמים, המתוארך לשנה 621 לספה\"נ, כשנה לפני ההג'רה למדינה.","מספר התפילות בקוראן לא נותן בהירות חד־משמעית, שכן הקוראן אינו מציג במקום אחד רשימה מפורשת של חמש התפילות היומיות. זמני התפילות ומספרן נקבעו במסגרת המסורות הנבואיות והפרקטיקה המוסלמית."]},{id:"pr-2",kind:"content",section:"התפילה",title:"חמש התפילות וזמניהן",content:["על המוסלמי להתפלל חמש תפילות ביום בזמנים קבועים (שעות זמניות כמו ביהדות).","תפילת השחר (צלאה אלפג'ר) זמנה בעלות השחר, כשהאדם יכול להבחין בין חוט לבן לחוט שחור (קוראן 2:187).","תפילת הצהריים (צלאה אלט'הר) זמנה בחצות היום.","תפילת אחר הצהריים (צלאה אלעצר) זמנה (לפי רוב האסכולות ההלכתיות באסלאם) כשאורכו של צל של עצם שווה לאורך העצם עצמו בתוספת צל השמש.","תפילת הערב (צלאה אלמע'רב) זמנה בשקיעת השמש.","תפילת הלילה (צלאה אלעשאא') זמנה בצאת הכוכבים ועד הבוקר."]},{id:"pr-v1",kind:"visual",section:"התפילה",title:"מחזור היום ותפילותיו",lead:"אותן חמש תפילות שקראתם עליהן, על ציר של יום אחד."},{id:"pr-3",kind:"content",section:"התפילה",title:"היטהרות וכוונה",content:["המוסלמי נדרש להיטהר לקראת התפילה (וד'וא) באמצעות רחיצת הידיים והפנים, רחיצת הזרועות עד המרפקים, ניגוב הראש ושטיפת הרגליים עד הקרסוליים. יש שינויים קלים בין הסונים לשיעים (ראו להלן: האסלאם השיעי).","על המוסלמי להתפלל בכוונה (נייה), אחרת התפילה תיחשב לו כמעשה רע שעשה."]},{id:"pr-4",kind:"content",section:"התפילה",title:"היכן מתפללים ומה מייחד את יום שישי",content:["המוסלמי אינו מחויב להתפלל במסגד ורשאי להתפלל היכן שנמצא בשעת התפילה, אך לתפילת יום השישי (צלאת אלג'מעה) מצווה המוסלמי להגיע למסגד ולשמוע דרשה (ח'טבה) מהאמאם של המסגד.",'מקובל כי תפילה "בציבור" במסגד היא במינימום של שלושה או ארבעה גברים, אך גם כאן יש שיטות שונות.',"אישה מחויבת להתפלל כמו גבר, אך אינה מצווה ללכת למסגד לתפילת יום השישי."]},{id:"pr-5",kind:"content",section:"התפילה",title:"כיוון התפילה",content:["כיוון התפילה (קבלה) הוא לעבר העיר מכה.","חשוב לציין כי בתקופה הראשונה של מוחמד במדינה (יש המציינים 17 חודשים), כיוון התפילה היה ירושלים, עד שמוחמד, ייתכן בשל מורת רוחו מהיהודים במדינה שלא המירו את דתם לאסלאם, קיבל התגלות (קוראן 2:144) שבה נאמר לו להפנות את פניו למכה.","שני דברים ראויים לציון:","האחד, קדושתה של ירושלים, בין היתר, היא בשל היותה כיוון התפילה הראשון (אלקבלה אלאולא או אולא אלקבלתין).",'השני, בעיר מדינה קיים מסגד הנקרא "בעל שני כיווני התפילה", שלפי המסורת ההתגלות שמוחמד קיבל להפנות את פניו למכה הייתה במהלך התפילה במסגד ההוא.']},{id:"pr-v2",kind:"visual",section:"התפילה",title:"שינוי כיוון התפילה",lead:"שבעה־עשר החודשים במדינה, ונקודת ההתגלות שבה הופנה הכיוון למכה."},{id:"pr-c",kind:"check",section:"התפילה",title:"בדיקת הבנה קצרה",check:{type:"match",instruction:"התאימו כל תפילה לזמן שבו היא מתקיימת.",pairs:[{left:"תפילת השחר",right:"עלות השחר"},{left:"תפילת הצהריים",right:"חצות היום"},{left:"תפילת אחר הצהריים",right:"כשצלו של החפץ שווה לגודלו"},{left:"תפילת הערב",right:"שקיעת השמש"},{left:"תפילת הלילה",right:"צאת הכוכבים ועד הבוקר"}],ok:"נכון. חמש התפילות פרושות על היום כולו: מעלות השחר, דרך חצות היום והצל המתארך, אל השקיעה וצאת הכוכבים.",try:"ההתאמה הזו אינה מדויקת. היא הוחזרה למקומה — נסו שוב.",hint:"עקבו אחר מחזור היום: מעלות השחר, דרך חצות היום והצל המשתווה לגודל החפץ, אל השקיעה ואל צאת הכוכבים."}},{id:"pr-t",kind:"transition",section:"התפילה",title:"סיום התפילה",text:"סיימנו את התפילה – מצווה המלווה את המוסלמי לאורך היום. כעת נעבור למצוות הצדקה.",nextLabel:"עוברים לצדקה"},{id:"ch-1",kind:"content",section:"הצדקה",title:"שיעור הצדקה ומקבליה",content:["המוסלמי מחויב לתת 2.5% מהמאזן השנתי שלו לצדקה (1/40, השוו: עין יפה), לעניים, נזקקים, יתומים, בתי תמחוי ועוד."]},{id:"ch-2",kind:"content",section:"הצדקה",title:"השכר, החובה והצדקות הנוספות",content:['צדקה זו מוזכרת מספר פעמים בקוראן, תוך הבטחה שנותן הצדקה יקבל שכר "בכפליים".','ה"זכאה" היא חובה דתית, ושונה מן הצדקה הוולנטרית שאינה מוגבלת לשיעור קבוע, וכן שונה מצדקה שמחויב המוסלמי לתת בעיד אלפטר (זכאה אלפטר) ובמועדים נוספים.']},{id:"ch-v",kind:"visual",section:"הצדקה",title:"2.5% מן המאזן",lead:"השיעור שקראתם עליו, ומה קורה כשהוא יוצא מן המאזן אל הקהילה."},{id:"ch-c",kind:"check",section:"הצדקה",title:"בדיקת הבנה קצרה",check:{type:"single",question:"המאזן השנתי של אדם הוא 10,000 שקלים. כמה עליו לתת לצדקה לפי שיעור של 2.5%?",instruction:"בחרו תשובה אחת.",options:[{text:"25 שקלים",right:!1},{text:"250 שקלים",right:!0},{text:"1,000 שקלים",right:!1},{text:"2,500 שקלים",right:!1}],ok:"נכון. 2.5% מתוך 10,000 הם 250. הצדקה מיועדת בין היתר לעניים, לנזקקים, ליתומים ולבתי תמחוי.",try:"לא מדויק. חשבו כמה הם 2.5% מתוך 10,000.",hint:"1% מתוך 10,000 הוא 100."}},{id:"ch-t",kind:"transition",section:"הצדקה",title:"סיום הצדקה",text:"סיימנו את הצדקה – חובה המבטאת אחריות כלפי הזולת והקהילה. כעת נעבור לצום רמדאן.",nextLabel:"עוברים לרמדאן"},{id:"rm-1",kind:"content",section:"צום רמדאן",title:"הצום לפני האסלאם ובראשיתו",content:["ידוע מהמקורות האסלאמיים כי בתקופה הטרום־אסלאמית הערבים בחצי האי ערב היו נוהגים לצום במהלך השנה ימים מסוימים, אך לא ניתן לדעת באופן מדויק מה הייתה הסיבה לכך.","בראשית האסלאם, ככל הידוע, הצום החל להתפתח בתקופת שהותו של מוחמד במדינה (לאחר שנת 622)."]},{id:"rm-2",kind:"content",section:"צום רמדאן",title:"החדית' על צום יום הכיפורים",content:["ישנו חדית' מוכר ומהימן במסורת האסלאמית, המובא בצחיח אלבוח'ארי (כתאב אלצום, פרק 69), על כך שכאשר מוחמד הגיע למדינה וראה יהודים צמים את יום הכיפורים (העשור לחודש – עאשוראא'), שאל אותם לפשר הצום.","היהודים ענו לו כי זהו יום טוב (יום צאלח), כי ביום הזה אללה הושיע אותם מפרעה, ומשה צם בו.","מוחמד ענה להם כי הוא ראוי למשה יותר מהם, וציווה על מאמיניו לצום בו."]},{id:"rm-3",kind:"content",section:"צום רמדאן",title:"מחודש רמדאן אל ליל אלקדר",content:["התפתחות הצום לחודש רמדאן הייתה מספר שנים לאחר הגירתו של מוחמד למדינה, עקב פסוק בקוראן, בו נאמר כי חודש רמדאן שבו ירד הקוראן, על המוסלמים לצום.",'ירידת הקוראן כאמור היא ההתגלות הראשונה שחווה מוחמד, לפי המסורת האסלאמית בשנת 610, בלילה ה־27 לחודש, המכונה "ליל אלקדר". יש מסורות נוספות על קביעת התאריך המדויק של ליל אלקדר.']},{id:"rm-4",kind:"content",section:"צום רמדאן",title:"יום הצום",content:["נאסר על המוסלמי לאכול, לשתות ולעשן מעלות השחר ועד לשקיעת החמה. אז שובר המוסלמי את הצום בסעודה קלה הנקראת אפטאר, ולאחר מכן נהוג ללכת למסגד להתפלל תפילות תראויח."]},{id:"rm-v",kind:"visual",section:"צום רמדאן",title:"מעלות השחר עד התראויח",lead:"יום צום אחד, מן האור הראשון ועד לתפילות שאחרי האפטאר."},{id:"rm-5",kind:"content",section:"צום רמדאן",title:"עשרת הלילות האחרונים",content:["עשרת הלילות האחרונים של חודש רמדאן קדושים במיוחד, ורבו המסורות עליהם. עיקרן התקרבות לאללה, עבודת המידות בין אדם לחברו ושליטה עצמית על לשונו.","המסורת המוסלמית אומרת בשם מוחמד כי מי שצם לשם שמים בחודש רמדאן, כל עוונות העבר נמחלות לו."]},{id:"rm-6",kind:"content",section:"צום רמדאן",title:"עיד אלפטר",content:["עם סיום חודש רמדאן ותחילת חודש שוואל מתחיל חג שבירת הצום (עיד אלפטר), שבמהלכו מרבים המוסלמים בארוחות משפחתיות משותפות, קונים בגדים ותכשיטים חדשים, וכן מצווה המוסלמי לתת צדקה נוספת מעבר לצדקה השנתית.","עיד אלפטר הוא זמן שבו מבקרים קרובי משפחה (צלת אלרחם), ואף מתפייסים עם קרובים שאיתם יש ריב או משקעי עבר."]},{id:"rm-7",kind:"content",section:"צום רמדאן",title:"ראיית הירח",content:['חודש רמדאן מתחיל ומסתיים ב"ראיית הירח" (רואית אלהלאל), ולעיתים יש שינויים (באסלאם הסוני) בין האסכולה הסעודית, הקובעת את תחילת וסוף החודש על פי ראיית המולד בטלסקופ (המולד האמיתי), לבין האסכולה המצרית, הקובעת את המולד לפי חישובים אסטרונומיים (המולד הממוצע).',"להרחבה ראו להלן: לוח השנה ההג'רי."]},{id:"rm-c",kind:"check",section:"צום רמדאן",title:"בדיקת הבנה קצרה",check:{type:"order",instruction:"סדרו את שלבי יום הצום לפי הסדר.",steps:["עלות השחר","הימנעות מאכילה, משתייה ומעישון","שקיעת החמה","אפטאר","תפילות תראויח"],ok:"נכון. הצום מתחיל בעלות השחר, נמשך לאורך היום, נשבר בשקיעה באפטאר, ולאחריו תפילות התראויח.",try:"השלב הזה אינו במקומו. הוא הוחזר לבנק — נסו שוב.",hint:"היום מתחיל באור הראשון ונשבר עם השקיעה. כל מה שבא אחרי השקיעה שייך כבר ללילה."}},{id:"rm-t",kind:"transition",section:"צום רמדאן",title:"סיום צום רמדאן",text:"סיימנו את צום רמדאן – חודש של צום, התקרבות לאללה ושליטה עצמית. כעת נצא למסע החג'.",nextLabel:"עוברים לחג'"},{id:"hj-1",kind:"content",section:"החג'",title:"מי עולה לרגל, מתי ולמה",content:["העלייה לרגל היא ריטואל המתקשר לאירועים שחוו הגר וישמעאל כשגורשו מביתו של אברהם, לפי המסורת המוסלמית, והטקסים המרכזיים של החג' מתקיימים בין היום ה־8 ל־13 לחודש ד'ו אלחג'ה, החודש ה־12 בלוח השנה ההג'רי.",'הנרטיב הנ"ל התקבל באסלאם, מפני שהיה קושי להגן על מנהג פגאני מובהק שהתקיים בחצי האי ערב, בכעבה, עוד הרבה לפני תקופת האסלאם.',"בראשית תקופת האסלאם היה קושי גדול להתנייד לחצי האי ערב, והדבר היה כרוך בהליכה ימים רבים במדבריות תוך סכנה גדולה משודדים, חיות רעות, חום המדבר ועוד.","בשל כך העלייה לרגל, הגם והיא חובה דתית, אינה כמו שאר מצוות היסוד, אלא תלויה ביכולתו של האדם, הן בהיבט הכלכלי והן בהיבט הבריאותי, והמוסלמי נדרש להתאמץ לשם כך עד גבול מסוים, פעם אחת במהלך חייו."]},{id:"hj-2",kind:"content",section:"החג'",title:"אחראם — לפני חציית המיקאת",content:["על המוסלמי העולה לרגל להיכנס למצב של טהרה (אחראם).","עליו להתגלח, להסתפר, לקצוץ את ציפורניו, ולאחר מכן להתעטף בבגד לבן המקיף את כתפו (רדאא), וכן בבגד לבן נוסף המקיף את מותניו (אזאר).","על הבגדים להיות ללא תפרים או כפלים, אלא חלקים.","חובת ההיטהרות מתחילה מאז שהמוסלמי מתקרב לאזור גאוגרפי מסוים סמוך למכה (נקרא בערבית מיקאת)."]},{id:"hj-3",kind:"content",section:"החג'",title:"טוואף — הקפת הכעבה",content:["הטקס הפולחני הראשון הוא הקפת הכעבה (טוואף) שבע פעמים (שבע הוא מספר טיפולוגי בתחומים רבים) נגד כיוון השעון, תוך אמירת פסוקי קוראן ודברי שבח לאללה."]},{id:"hj-4",kind:"content",section:"החג'",title:"סעי — בין צפא ומרוה",content:["הטקס הפולחני השני הוא המעבר בין הגבעות צפא ומרוה (סעי), כאשר בקטעים מסוימים של המסלול נוהגים לרוץ.","ריצה זו מתקשרת לריצתה של הגר בין שתי הגבעות הללו במהלך חיפוש אחר מים לבנה ישמעאל, עד שהמלאך גבריאל המציא מבין שתי הגבעות את מעיין הזמזם, הנודע בקדושתו ובסגולותיו באסלאם."]},{id:"hj-5",kind:"content",section:"החג'",title:"העמידה במישור ערפה",content:['הטקס הפולחני השלישי, והחשוב ביותר מבין כולם, הוא העמידה במישור ערפה למרגלות "ג\'בל אלרחמה" (הר הרחמים).',"המוסלמי נוסע למישור ערפה, הנמצא מספר קילומטרים ממכה, ומתכונן לפולחן סביב ההר, מצהרי היום השני של החג' ועד לבוקרו של היום השלישי.",'ביום הזה הוא עולה להר (מוסלמים רבים נוהגים לצום בו), תוך כדי קריאת תפילות (תלביה), ועם ירידתו עומד במישור ערפה ומבצע את ה"עמידה" (וקוף).',"ההר באסלאם נחשב להר קדוש, ומסורות רבות סופרו על אודותיו. בין היתר, שזהו ההר שאדם וחוה ידעו זה את זו לאחר גירושם מגן עדן, וכן ההר שעליו עקד אברהם את ישמעאל בנו, לפי המסורת האסלאמית."]},{id:"hj-6",kind:"content",section:"החג'",title:"מוזדליפה ומינא",content:["עם סיום הווקוף ולקראת ערב חוזר המוסלמי למכה, ועוצר במקום הנקרא מוזדליפה.",'שם הוא אוסף אבנים ונוסע ל"מינא", שם הוא מבצע טקס של זריקת אבנים על השטן (ג\'מאראת).',"רגימת השטן באבנים היא לזכר כך שהשטן ניסה לפתות את אברהם שלא לעקוד את ישמעאל בנו לעולה, וזריקת האבנים מסמלת את הנזיפה שקיבל כאשר לא עלה בידו לפתות את אברהם."]},{id:"hj-v",kind:"visual",section:"החג'",title:"מפת מסע החג'",lead:"התחנות שקראתם עליהן, לפי סדרן על המסלול."},{id:"hj-7",kind:"content",section:"החג'",title:"חג הקורבן וברכת הדרך",content:["עם החזרה למכה מתחיל חג הקורבן (עיד אלאדחא), המתבטא בשחיטת כבש, לזכר הכבש ששחט אברהם במקום את בנו ישמעאל.","חג הקורבן נמשך ארבעה ימים, והיום הראשון שלו מתחיל בעוד טקסי החג' בעיצומן.","עם סיום חג הקורבן מבצע המוסלמי הקפות נוספות סביב הכעבה.","ברכה רווחת בתקופת החג' היא:","حج مبرور وسعي مشكور وذنب مغفور","חג' מברור, וסעי משכור וד'נב מע'פור",'"חג מקובל, טקס הריצה רצוי ומבורך והחטא נמחל."']},{id:"hj-c",kind:"check",section:"החג'",title:"בדיקת הבנה קצרה",check:{type:"order",instruction:"סדרו את התחנות המרכזיות במסע העלייה לרגל.",steps:["אחראם","טוואף","סעי","ערפה","מוזדליפה","מינא","חזרה למכה"],ok:"נכון. זהו סדר התחנות: אחראם, טוואף, סעי, ערפה, מוזדליפה, מינא וחזרה למכה.",try:"התחנה הזו אינה במקומה. היא הוחזרה לבנק — נסו שוב.",hint:"היעזרו במפת המסע: ההיטהרות קודמת לכניסה למכה, והרגימה במינא באה אחרי העצירה במוזדליפה."}},{id:"hj-t",kind:"transition",section:"החג'",title:"סיום החג'",text:"סיימנו את החג' ואת ההיכרות עם חמש מצוות היסוד.",nextLabel:"לתרגול המסכם"},{id:"sum-c",kind:"check",section:"סיכום",title:"התרגול המסכם",check:{type:"situations",instruction:"התאימו כל סיטואציה למצוות היסוד המתאימה.",pairs:[{key:"shahada",text:"אדם מעיד שאין אל מבלעדי אללה ושמוחמד הוא שליחו",to:"השהאדה"},{key:"prayer",text:"אדם מתפלל חמש פעמים ביום",to:"התפילה"},{key:"charity",text:"אדם נותן 2.5% מהמאזן השנתי שלו לנזקקים",to:"הצדקה"},{key:"fast",text:"אדם נמנע מאכילה ומשתייה מעלות השחר ועד השקיעה",to:"צום רמדאן"},{key:"hajj",text:"אדם מקיף את הכעבה שבע פעמים",to:"החג'"}],ok:"כל אחת מחמש מצוות היסוד מתבטאת בפעולה אחרת, ויחד הן יוצרות מערכת אחת של אמונה, פולחן, אחריות, שליטה עצמית ושייכות.",try:"הסיטואציה הזו שייכת למצווה אחרת. היא הוחזרה למקומה — נסו שוב."}},{id:"sum-end",kind:"finish",section:"סיכום",title:"סיום הפרק"}]}}}]);